    if (!e) return void renderKfcNormalOffers(kfcNormalOffers, !1);
    renderKfcNormalOffers(kfcNormalOffers.filter(t => String(t.detail).toLocaleLowerCase("zh-Hant-TW").includes(e)), !0)
