    const t = "loading" === e || "error" === e;
    kfcNormalElements.search.disabled = t, "loading" === e && (kfcNormalElements.grid.replaceChildren(), kfcNormalElements.loadingText ? kfcNormalElements.count.textContent = kfcNormalElements.loadingText.textContent : kfcNormalElements.count.textContent = "正在取得優惠資料..."), "error" === e && (kfcNormalElements.grid.replaceChildren(), kfcNormalElements.count.textContent = "優惠資料載入失敗")
